'use strict';
const $ = (q)=>document.querySelector(q);
const app = $('#screen');
const rupee = (n)=>'₹'+Number(n||0).toLocaleString('en-IN');
const esc = (v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr = esc;
const todayLocal = ()=>{const t=new Date();return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;};
const future = ()=>{const d=new Date();d.setDate(d.getDate()+1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const readStore=(key,defaultVal)=>{try{return JSON.parse(localStorage.getItem(key))??defaultVal;}catch{return defaultVal}};
let S={view:'home',mode:'TRAIN',user:null,stations:[],date:future(),from:'Bengaluru',to:'Chennai',results:[],hasSearched:false,query:'',selected:null,travelClass:'Sleeper',count:1,selectedSeats:[],passengers:[{name:'',age:'',gender:'Female'}],insurance:false,checkout:null,paymentMode:'UPI QR',paymentStage:0,ticket:null,tickets:[],board:[],boardStation:'Bengaluru',adminStats:null,adminServices:[],history:readStore('ry_history',[]),theme:localStorage.getItem('ry_theme')||'light',lang:localStorage.getItem('ry_lang')||'en',langShown:false,authReturn:'home',publicDemo:false};
const languages={en:'English',hi:'हिन्दी',te:'తెలుగు',kn:'ಕನ್ನಡ',ta:'தமிழ்',bn:'বাংলা',mr:'मराठी',ml:'മലയാളം'};
const words={
 en:{home:'Explore',tickets:'My tickets',board:'Station board',help:'Help',login:'Login',search:'Find journeys',from:'From station',to:'To station',date:'Travel date',train:'Train tickets',flight:'Flights',sign:'Create account'},
 hi:{home:'यात्रा खोजें',tickets:'मेरे टिकट',board:'स्टेशन बोर्ड',help:'सहायता',login:'लॉग इन',search:'यात्राएँ खोजें',from:'कहाँ से',to:'कहाँ तक',date:'यात्रा की तारीख',train:'रेल टिकट',flight:'उड़ानें',sign:'खाता बनाएँ'},
 te:{home:'ప్రయాణాలు',tickets:'నా టికెట్లు',board:'స్టేషన్ బోర్డు',help:'సహాయం',login:'లాగిన్',search:'ప్రయాణాలు వెతకండి',from:'ఎక్కడి నుంచి',to:'ఎక్కడికి',date:'ప్రయాణ తేదీ',train:'రైలు టికెట్లు',flight:'విమానాలు',sign:'ఖాతా సృష్టించండి'},
 kn:{home:'ಪ್ರಯಾಣಗಳು',tickets:'ನನ್ನ ಟಿಕೆಟ್‌ಗಳು',board:'ನಿಲ್ದಾಣ ಫಲಕ',help:'ಸಹಾಯ',login:'ಲಾಗಿನ್',search:'ಪ್ರಯಾಣ ಹುಡುಕಿ',from:'ಎಲ್ಲಿಂದ',to:'ಎಲ್ಲಿಗೆ',date:'ಪ್ರಯಾಣ ದಿನಾಂಕ',train:'ರೈಲು ಟಿಕೆಟ್',flight:'ವಿಮಾನಗಳು',sign:'ಖಾತೆ ರಚಿಸಿ'},
 ta:{home:'பயணங்கள்',tickets:'என் டிக்கெட்டுகள்',board:'நிலைய பலகை',help:'உதவி',login:'உள்நுழை',search:'பயணங்களை தேடு',from:'புறப்படும் இடம்',to:'செல்லும் இடம்',date:'பயண தேதி',train:'ரயில் டிக்கெட்',flight:'விமானங்கள்',sign:'கணக்கு உருவாக்கு'}
};
const t=(key)=>(words[S.lang]||words.en)[key]||words.en[key]||key;
const encode=(data)=>new URLSearchParams(data).toString();
async function api(path,values){
 const req=values===undefined?{credentials:'same-origin'}:{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:encode(values),credentials:'same-origin'};
 const response=await fetch(path,req);let res;
 try{res=await response.json();}catch{throw Error('Cannot connect to Java server. Is it running?')}
 if(!response.ok||!res.ok)throw Error(res.error||'Operation failed');return res.data;
}
function msg(text){const toast=$('#toast');toast.textContent=text;toast.classList.add('show');clearTimeout(window._ryToast);window._ryToast=setTimeout(()=>toast.classList.remove('show'),3500)}
function moneyInfo(){let x=S.selected;if(!x)return {fare:0,fee:19,tax:0,insurance:0,total:0};const n=S.count,cl=S.travelClass;
 const mult=x.type==='TRAIN'?({Sleeper:1,'3A':1.55,'2A':2.15,'1A':3}[cl]||1):({Economy:1,'Premium Economy':1.6,Business:2.6}[cl]||1);
 const fare=Math.round(x.fare*mult*n),tax=Math.round(fare*.05),fee=19,insurance=S.insurance?n*15:0;return {fare,tax,fee,insurance,total:fare+tax+fee+insurance};
}
const first=(name)=>esc(name?.split(' ')[0]||'Traveler');
const heading=(title,desc,action='')=>`<div class="content-header"><div><h2>${title}</h2><p class="section-sub">${desc}</p></div>${action}</div>`;
const back=(view='home')=>`<button class="backlink" data-go="${view}">← Back to ${view==='home'?'explore':view==='tickets'?'my tickets':'previous page'}</button>`;
function authHeader(){const p=$('#auth-pill');p.innerHTML=S.user?
 `<div class="top-auth"><button class="user-chip" data-go="tickets"><span class="avatar">${esc(S.user.name?.charAt(0).toUpperCase())}</span>${first(S.user.name)}</button></div>`:
 `<div class="top-auth"><button class="btn btn-white btn-sm" data-action="login">${t('login')}</button></div>`;
 document.querySelectorAll('[data-nav]').forEach(el=>{el.classList.toggle('nav-current',el.dataset.nav===S.view)});
}
function options(selected){return S.stations.map(n=>`<option value="${attr(n)}" ${n===selected?'selected':''}>${esc(n)}</option>`).join('')}
function changeMode(type){S.mode=type;S.query='';S.hasSearched=false;S.results=[];S.from='Bengaluru';S.to=type==='TRAIN'?'Chennai':'Delhi';S.travelClass=type==='TRAIN'?'Sleeper':'Economy';go('home');search(false)}
async function search(write=true){
 try{
  const qs=new URLSearchParams({type:S.mode,date:S.date});if(S.query)qs.set('q',S.query);else{qs.set('from',S.from);qs.set('to',S.to)}
  const result=await api('/api/services?'+qs.toString());S.results=result.services;S.hasSearched=true;
  if(write&&!S.query){S.history=[{type:S.mode,from:S.from,to:S.to,date:S.date},...S.history.filter(h=>!(h.type===S.mode&&h.from===S.from&&h.to===S.to))].slice(0,6);localStorage.setItem('ry_history',JSON.stringify(S.history));}
  render();if(write)$('#search-results')?.scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){msg(e.message)}
}
function home(){
 const isTrain=S.mode==='TRAIN';const hist=S.history.slice(0,4).map((h,i)=>`<button class="history-chip" data-history="${i}">${h.type==='TRAIN'?'🚆':'✈️'} ${esc(h.from)} → ${esc(h.to)}</button>`).join('');
 return `<section class="hero"><div class="max"><div class="hero-upper"><div><span class="eyebrow">WELCOME TO RAILYATRA</span><h1>Every journey begins <em>beautifully.</em></h1><p class="hero-lead">Discover routes, compare fares, choose your own seat and enjoy a smooth booking experience — all in one place.</p><div class="hero-stats"><div class="hero-stat"><span class="stat-ico">🚆</span><div><b>27+</b><small>Sample train routes</small></div></div><div class="hero-stat"><span class="stat-ico">✈️</span><div><b>15+</b><small>Sample flights</small></div></div><div class="hero-stat"><span class="stat-ico">🔒</span><div><b>100%</b><small>Demo payments</small></div></div></div></div><div class="hero-art" aria-hidden="true"><div class="boarding-card"><div class="boarding-top"><b>🚆 RAILYATRA</b><span>BOARDING PASS · DEMO</span></div><div class="boarding-route"><div><b>SBC</b><small>Bengaluru</small></div><div class="line">🚆</div><div><b>MAS</b><small>Chennai</small></div></div><div class="boarding-lower"><div><span class="muted tiny">JOURNEY</span><br><b>YOUR NEXT STORY</b></div><div class="barcode"></div></div></div></div></div></div></section>
 <div class="max finder-wrap"><div class="finder"><div class="finder-top"><div class="tabs"><button class="tab ${isTrain?'active':''}" data-mode="TRAIN">🚆 ${t('train')}</button><button class="tab ${!isTrain?'active':''}" data-mode="FLIGHT">✈️ ${t('flight')}</button></div><span class="soft-pill">✨ Effortless booking</span></div>
 <form id="search-form" class="finder-body"><div class="field-wrap"><label>${t('from')}</label><div class="inputbox"><span class="prefix">◉</span><select id="from" aria-label="From station">${options(S.from)}</select></div></div><button type="button" class="swap" data-action="swap" aria-label="Swap stations">⇅</button><div class="field-wrap"><label>${t('to')}</label><div class="inputbox"><span class="prefix">📍</span><select id="to" aria-label="To station">${options(S.to)}</select></div></div><div class="field-wrap"><label>${t('date')}</label><div class="inputbox"><span class="prefix">📅</span><input type="date" id="search-date" value="${attr(S.date)}" min="${todayLocal()}" required></div></div><button type="submit" class="btn btn-primary search-action">🔎 ${t('search')}</button></form>
 <div class="tiny-disclaimer"><span>Easy seat selection</span><span>Detailed e-ticket</span><span>Local demo data</span><span>No real money charged</span></div></div></div>
 <main class="max content"><div class="quick-grid"><button class="quick-card" data-action="open-number"><span class="quick-icon">🔎</span><span style="flex:1"><strong>Train / flight number</strong><small>Search by name or number</small></span><span>→</span></button><button class="quick-card" data-go="board"><span class="quick-icon">📡</span><span style="flex:1"><strong>Station departure board</strong><small>Timetable with demo delay status</small></span><span>→</span></button><button class="quick-card" data-go="tickets"><span class="quick-icon">🎟️</span><span style="flex:1"><strong>My bookings</strong><small>Ticket, PNR and cancellation</small></span><span>→</span></button></div>
 ${S.history.length?`<div class="detail-flex"><h4 style="margin:0 0 12px">Recent searches</h4><button class="plain-link tiny" data-action="clear-history">Clear history</button></div><div class="history-wrap">${hist}</div>`:''}
 <div id="search-results">${heading(S.query?`Search results for “${esc(S.query)}”`:isTrain?'Available trains':'Available flights',S.hasSearched?`${S.results.length} sample ${isTrain?'trains':'flights'} found · Timetables are illustrative`:'Search a journey to see options',`<span class="soft-pill">${esc(S.date)}</span>`)}
 <div class="results">${S.results.length?S.results.map(serviceCard).join(''):`<div class="empty"><div class="empty-illustration"></div><h3>${S.hasSearched?'No matching journeys':'Where will you travel next?'}</h3><p class="muted">${S.hasSearched?'Try another route or search by train number.':'Your trips, destinations and bookings will appear here.'}</p><button class="btn btn-light" data-action="open-number">Search by number</button></div>`}</div></div>
 ${heading('Travel tools for your journey','Everything you need before, during, and after a trip')}
 <div class="coming-grid"><div class="coming-item"><b>📍 Station guide</b><small class="muted">Browse sample station departure times and expected platform waiting information.</small></div><div class="coming-item"><b>🪑 Seat availability</b><small class="muted">See reserved seats and choose free seats on a specific date.</small></div><div class="coming-item"><b>🧾 Booking & cancellations</b><small class="muted">View complete tickets, fare breakdowns, cancellation time, and demo refund.</small></div></div></main>`;
}
function serviceCard(x){let isFlight=x.type==='FLIGHT',status=x.delayMinutes?`+${x.delayMinutes} min demo delay`:'On time (demo)';
 return `<article class="service-card"><div class="service-heading"><div class="service-name"><span class="service-ico">${isFlight?'✈️':'🚆'}</span><div><h3>${esc(x.name)}</h3><small>${esc(x.number)} · ${isFlight?'Daily flight · sample':'Daily train · sample'}</small></div></div><span class="tag ${x.delayMinutes?'warn':'success'}">● ${status}</span></div>
 <div class="service-lower"><div class="route-timeline"><div><strong>${esc(x.departure)}</strong><small>${esc(x.from)}</small></div><div class="route-line"><small>${esc(x.duration)}</small><span class="rail"></span><small>${isFlight?'✈ Flight':'🚆 Train'}</small></div><div style="text-align:right"><strong>${esc(x.arrival)}</strong><small>${esc(x.to)}</small></div></div>
 <div class="meta-pair"><small>Availability / waiting</small><b class="${x.remaining<5?'danger-text':'success-text'}">${x.remaining} seats available</b><small>${esc(x.waitlist)} · 0 booked waitlist</small></div>
 <div class="service-price">${rupee(x.fare)}<small>base fare / person</small></div>
 <div class="book-action"><button class="btn btn-primary" data-book="${attr(x.id)}">View & book →</button></div></div>
 <div class="tiny-disclaimer" style="margin-top:14px"><span>${esc(x.days)}</span><span>Travel time ${esc(x.duration)}</span><span>Sample schedule, not live tracking</span></div></article>`;
}
function classOptions(){const cs=S.selected.type==='TRAIN'?['Sleeper','3A','2A','1A']:['Economy','Premium Economy','Business'];return cs.map(c=>`<option ${c===S.travelClass?'selected':''}>${c}</option>`).join('')}
function seatMap(){const x=S.selected,occupied=x.occupiedSeats||[],total=x.capacity;return `<div class="seat-grid">${Array.from({length:total},(_,i)=>{const n=i+1,taken=occupied.includes(n),selected=S.selectedSeats.includes(n);return `<button class="seat ${(i%8===3)?'aisle':''} ${taken?'taken':''} ${selected?'selected':''}" data-seat="${n}" type="button" ${taken?'disabled':''} title="Seat ${n}${taken?' booked':''}">${x.type==='TRAIN'?'S':''}${n}</button>`}).join('')}</div>`}
function steps(current){return `<div class="steps">${['Choose journey','Passengers','Demo payment','E-ticket'].map((v,i)=>`${i?'<div class="step-spacer"></div>':''}<div class="step ${i<current?'done':i===current?'active':''}"><b>${i<current?'✓':i+1}</b><span>${v}</span></div>`).join('')}</div>`}
function farePanel(info,buttonLabel='',onClick=''){const x=S.selected;return `<aside class="panel trip-summary"><h3>🧾 Fare summary</h3><div class="summary-row"><span>${esc(x.type==='TRAIN'?'Train':'Flight')}</span><strong>${esc(x.number)}</strong></div><div class="summary-row"><span>Route</span><strong>${esc(x.from)} → ${esc(x.to)}</strong></div><div class="summary-row"><span>Date / class</span><strong>${esc(S.date)}<br>${esc(S.travelClass)}</strong></div><div class="summary-row"><span>Passengers / seats</span><strong>${S.count} · ${S.selectedSeats.length?S.selectedSeats.map(n=>'S'+n).join(', '):'Not selected'}</strong></div><div class="separator"></div><div class="summary-row"><span>Base fare</span><strong>${rupee(info.fare)}</strong></div><div class="summary-row"><span>Taxes (demo 5%)</span><strong>${rupee(info.tax)}</strong></div><div class="summary-row"><span>Convenience fee</span><strong>${rupee(info.fee)}</strong></div><div class="summary-row"><span>Travel insurance (demo)</span><strong>${rupee(info.insurance)}</strong></div><div class="summary-total"><span>Total amount</span><b>${rupee(info.total)}</b></div><div class="banner warning" style="margin-top:16px">🔒 Demo checkout: all amounts are simulated. No actual payment or reservation is made.</div>${buttonLabel?`<button class="btn btn-primary btn-wide" style="margin-top:15px" data-action="${onClick}">${buttonLabel}</button>`:''}</aside>`;}
function booking(){if(!S.selected)return '<main class="max content">No journey selected.</main>';const x=S.selected,info=moneyInfo();
 return `<main class="max content">${back()}${steps(1)}${heading('Passenger information & seat choice',`${esc(x.name)} · ${esc(x.from)} → ${esc(x.to)} · ${esc(S.date)}`)}
 <div class="detail-grid"><section><div class="panel"><div class="detail-flex"><div><h3>🚆 ${x.type==='FLIGHT'?'Flight':'Train'} details</h3><p class="muted tiny">${esc(x.number)} · ${esc(x.duration)} · ${x.remaining} seats available</p></div><span class="tag success">Date-wise availability</span></div><div class="route-timeline"><div><strong>${esc(x.departure)}</strong><small>${esc(x.from)}</small></div><div class="route-line"><small>${esc(x.duration)}</small><span class="rail"></span></div><div style="text-align:right"><strong>${esc(x.arrival)}</strong><small>${esc(x.to)}</small></div></div><div class="banner" style="margin-top:16px">⏱ Expected ${x.delayMinutes?'delay '+x.delayMinutes+' minutes':'on-time service'} (sample information). No live GPS feed is connected.</div></div>
 <div class="panel"><div class="detail-flex"><h3>👥 Add passengers</h3><div style="display:flex;gap:8px"><button class="btn btn-outline btn-sm" data-action="remove-passenger" ${S.count<=1?'disabled':''}>−</button><span class="strong" style="align-self:center">${S.count} / 6</span><button class="btn btn-outline btn-sm" data-action="add-passenger" ${S.count>=6?'disabled':''}>＋</button></div></div>
 <div class="field"><label>Travel class</label><select id="booking-class">${classOptions()}</select></div>
 ${Array.from({length:S.count},(_,i)=>{const p=S.passengers[i]||{name:'',age:'',gender:'Female'};return `<div class="separator"></div><p class="progress-label">Passenger ${i+1}</p><div class="form-grid"><div class="field"><label>Full name</label><input data-pfield="name" data-index="${i}" value="${attr(p.name)}" maxlength="80" placeholder="Name as on ID"></div><div class="field"><label>Age</label><input data-pfield="age" data-index="${i}" value="${attr(p.age)}" min="1" max="120" type="number" placeholder="Age"></div><div class="field"><label>Gender</label><select data-pfield="gender" data-index="${i}">${['Female','Male','Other'].map(g=>`<option ${p.gender===g?'selected':''}>${g}</option>`).join('')}</select></div></div>`}).join('')}
 </div><div class="panel"><div class="detail-flex"><div><h3>🪑 Choose your seats</h3><p class="muted tiny">Select exactly ${S.count} free ${S.count===1?'seat':'seats'} — ${S.selectedSeats.length} selected</p></div><span class="soft-pill">${x.capacity} total</span></div><div id="seat-container">${seatMap()}</div><div class="legend"><span><i class="dot"></i>Available</span><span><i class="dot sel"></i>Selected</span><span><i class="dot taken"></i>Already booked</span></div><label class="check-row"><input type="checkbox" id="insurance" ${S.insurance?'checked':''}><span>Add optional demo travel insurance (${rupee(15)} per passenger)</span></label><button class="btn btn-primary btn-wide" data-action="checkout">Continue to payment →</button></div></section>${farePanel(info)}</div></main>`;
}
const payMethods=[['UPI QR','▦'],['UPI ID','🔗'],['Google Pay','G'],['PhonePe','📱'],['Paytm','💠'],['Net Banking','🏦'],['Demo Card','💳']];
function payment(){const c=S.checkout;if(!c)return '<main class="max content">No checkout.</main>';const mode=S.paymentMode;
 return `<main class="max content">${back('home')}${steps(2)}${heading('Choose how to pay','Secure-looking checkout flow for learning only — NO real payments are taken')}
 <div class="detail-grid"><section><div class="panel"><div class="detail-flex"><h3>💳 Payment methods</h3><span class="tag warn">TEST MODE</span></div><p class="muted tiny">Choose a simulated payment option. Cash on delivery is unavailable for online bookings.</p><div class="pay-methods">${payMethods.map(([name,ico])=>`<button class="pay-option ${name===mode?'active':''}" data-pay="${attr(name)}"><span class="pay-ico">${ico}</span><b>${esc(name)}</b></button>`).join('')}</div><div class="separator"></div>
 <div id="payment-instructions">${paymentInstructions()}</div></div></section>${farePanel({fare:c.fare,tax:c.tax,fee:c.fee,insurance:c.insurance,total:c.total})}</div></main>`;
}
function paymentInstructions(){if(S.paymentStage===1)return `<div class="banner success">✅ Demo step completed. Continue to confirm a <b>simulated</b> payment and generate your sample e-ticket.</div><div class="panel" style="margin-top:14px"><h3>Review your demo payment</h3><div class="summary-row"><span>Selected mode</span><strong>${esc(S.paymentMode)}</strong></div><div class="summary-row"><span>Amount</span><strong>${rupee(S.checkout.total)}</strong></div><div class="summary-row"><span>Payment destination</span><strong>Test only — no real merchant</strong></div><label class="check-row"><input id="ack-demo" type="checkbox"><span>I understand this is a simulated payment and no money is transferred.</span></label><button class="btn btn-green btn-wide" data-action="complete-payment">✓ Confirm demo payment & book ticket</button><button class="btn btn-outline btn-wide" style="margin-top:8px" data-action="payment-back">← Change payment mode</button></div>`;
 const mode=S.paymentMode;let body;
 if(mode==='UPI QR')body=`<h3>Scan QR (demonstration)</h3><p class="muted">This pattern is deliberately <b>not scannable</b> and cannot collect money.</p><div class="demo-qr" aria-label="Unscannable demo-only payment graphic"></div><p style="text-align:center"><b>DEMO ONLY — ${rupee(S.checkout.total)}</b><br><small class="muted">Do not scan using a real payment application.</small></p>`;
 else if(mode==='UPI ID')body=`<h3>Demo UPI ID</h3><div class="inputbox"><span>🔗</span><input readonly value="demo@rail.invalid" aria-label="Demo UPI ID"></div><p class="muted tiny">The .invalid address is a sample placeholder. It is not a payment destination.</p>`;
 else if(['Google Pay','PhonePe','Paytm'].includes(mode))body=`<h3>${esc(mode)} — demo app hand-off</h3><div style="text-align:center;padding:25px 10px"><div style="font-size:51px">📱</div><h3>Opening ${esc(mode)} (simulation)</h3><p class="muted">In a real product, this would use an approved payment gateway. This demo does not open external payment apps or deduct money.</p></div>`;
 else if(mode==='Net Banking')body=`<h3>Choose a demo bank</h3><div class="field"><label>Sample bank</label><select><option>SBI (demo)</option><option>HDFC Bank (demo)</option><option>ICICI Bank (demo)</option><option>Axis Bank (demo)</option></select></div><div class="banner">No bank account, login, PIN or OTP is needed for this learning demo.</div>`;
 else body=`<h3>Demo card payment</h3><div class="banner">For safety, real card numbers, CVVs, and banking PINs are never collected. This is only a sample card-payment screen.</div><div class="field" style="margin-top:15px"><label>Example card brand</label><select><option>Visa (sample)</option><option>Mastercard (sample)</option><option>RuPay (sample)</option></select></div>`;
 return `${body}<div class="banner warning" style="margin-top:14px">⚠️ All payment steps are simulated. Press Next to continue without sending real money.</div><button class="btn btn-primary btn-wide" data-action="payment-next" style="margin-top:15px">Next — demo payment review →</button>`;
}
function statusBadge(status){return status==='CONFIRMED'?'<span class="tag success">✓ CONFIRMED</span>':'<span class="tag danger">✕ CANCELLED</span>'}
function bookingTile(x){const s=x.service;return `<article class="service-card"><div class="detail-flex"><div class="service-name"><span class="service-ico">${s.type==='FLIGHT'?'✈️':'🚆'}</span><div><h3>${esc(s.name)}</h3><small>${esc(x.pnr)} · ${esc(x.date)} · ${esc(s.number)}</small></div></div>${statusBadge(x.status)}</div><div class="route-timeline" style="margin:15px 0"><div><strong>${esc(s.departure)}</strong><small>${esc(s.from)}</small></div><div class="route-line"><small>${esc(s.duration)}</small><span class="rail"></span></div><div style="text-align:right"><strong>${esc(s.arrival)}</strong><small>${esc(s.to)}</small></div></div><div class="detail-flex"><div><span class="strong">${rupee(x.total)}</span><span class="muted tiny"> · ${x.passengers.length} passengers · ${x.seats.length} seats</span></div><button class="btn btn-primary btn-sm" data-ticket="${attr(x.pnr)}">View ticket →</button></div></article>`}
function tickets(){return `<main class="max content">${back()}${heading('My journeys','View tickets, booking receipts, passenger details, and cancellations')}
 ${S.user?`<div class="panel profile-strip" style="margin-bottom:18px"><span class="avatar">${esc(S.user.name[0])}</span><div><b>${esc(S.user.name)}</b><small>${esc(S.user.email)}</small></div></div>${S.tickets.length?`<div class="results">${S.tickets.map(bookingTile).join('')}</div>`:`<div class="empty"><div style="font-size:58px">🎫</div><h3>No bookings yet</h3><p class="muted">Your confirmed and cancelled demo tickets will appear here.</p><button class="btn btn-primary" data-go="home">Find a journey</button></div>`}`:`<div class="empty"><div style="font-size:55px">🔐</div><h3>Login to see your tickets</h3><p class="muted">Your saved tickets are connected to your local demo account.</p><button class="btn btn-primary" data-action="login">Login / Register</button></div>`}</main>`}
function ticketView(){const x=S.ticket;if(!x)return tickets();const s=x.service,cancelled=x.status==='CANCELLED';return `<main class="max content">${back('tickets')}${steps(3)}
 <div class="receipt"><div class="checkmark" style="${cancelled?'background:#fff0f0;color:#cf5762;border-color:#efb7bd':''}">${cancelled?'✕':'✓'}</div><h2>${cancelled?'Ticket cancellation confirmed':'Your journey is booked!'}</h2><p>${cancelled?`Cancelled on ${esc(x.cancelledAt)}. Seats released.`:`Demo payment completed · ${esc(x.paidAt)}`}</p><span class="tag ${cancelled?'danger':'success'}">${cancelled?'CANCELLED — DEMO':'BOOKING CONFIRMED — DEMO'}</span></div>
 <div class="ticket-paper ${cancelled?'cancelled':''}"><div class="ticket-band"><div><h3 style="margin:0;color:#fff">🚆 RAILYATRA E-TICKET</h3><span>DEMO DOCUMENT — NOT VALID FOR TRAVEL</span></div><div style="text-align:right"><small>PNR / Booking Ref</small><br><b>${esc(x.pnr)}</b></div></div><div class="ticket-body"><div class="detail-flex"><b>${esc(s.name)} · ${esc(s.number)}</b>${statusBadge(x.status)}</div><div class="ticket-route"><div><b>${esc(s.departure)}</b><small class="muted">${esc(s.from)}</small></div><div class="middle">${s.type==='FLIGHT'?'✈':'🚆'}</div><div style="text-align:right"><b>${esc(s.arrival)}</b><small class="muted">${esc(s.to)}</small></div></div>
 <div class="ticket-info"><div><small>Journey date</small><strong>${esc(x.date)}</strong></div><div><small>Travel class</small><strong>${esc(x.travelClass)}</strong></div><div><small>Travel duration</small><strong>${esc(s.duration)}</strong></div><div><small>Payment method</small><strong>${esc(x.method)}</strong></div><div><small>Payment reference</small><strong>${esc(x.paymentReference)}</strong></div><div><small>Demo paid on</small><strong>${esc(x.paidAt)}</strong></div></div>
 <div class="separator"></div><h4 style="margin-bottom:5px">Passengers and seats</h4>${x.passengers.map((p,i)=>`<div class="passenger-row"><span><b>${i+1}. ${esc(p.name)}</b> <span class="muted">· ${p.age} years · ${esc(p.gender)}</span></span><span class="tag">Seat ${esc(x.seats[i])}</span></div>`).join('')}
 <div class="separator"></div><h4 style="margin-bottom:6px">Payment summary</h4><div class="summary-row"><span>Base fare</span><strong>${rupee(x.fare)}</strong></div><div class="summary-row"><span>Tax</span><strong>${rupee(x.tax)}</strong></div><div class="summary-row"><span>Service fee</span><strong>${rupee(x.fee)}</strong></div><div class="summary-row"><span>Insurance</span><strong>${rupee(x.insurance)}</strong></div><div class="summary-total"><span>Total demo amount</span><b>${rupee(x.total)}</b></div>
 ${cancelled?`<div class="separator"></div><h4>Cancellation confirmation</h4><div class="banner danger">Your demo reservation was cancelled on <b>${esc(x.cancelledAt)}</b>. The assigned seats are now available again. This does not refund real money.</div><div class="summary-row"><span>Cancellation timestamp</span><strong>${esc(x.cancelledAt)}</strong></div><div class="summary-row"><span>Refund amount (simulated)</span><strong>${rupee(x.refund)}</strong></div><div class="summary-row"><span>Refund status</span><strong>${esc(x.refundStatus)}</strong></div>`:`<div class="banner success" style="margin-top:20px">✓ Your seat allocation is saved in the local demo database. Check your seat numbers above.</div>`}
 <div class="ticket-actions no-print"><button class="btn btn-primary" data-action="download-ticket">⬇ Download ticket</button><button class="btn btn-outline" data-action="print-ticket">🖨 Print</button>${cancelled?'':`<button class="btn btn-red" data-action="cancel-preview">✕ Cancel ticket</button>`}<button class="btn btn-light" data-go="tickets">My bookings</button></div></div></div>
 <div class="banner warning" style="margin-top:20px">This project is for presentation and testing. Sample service numbers/routes may resemble real services, but availability, departure status, flights and payments are not live.</div></main>`}
function board(){return `<main class="max content">${back()}${heading(t('board'),'Sample departure information, scheduled times, and illustrative delays')}
 <div class="panel"><div class="detail-flex"><div class="field" style="min-width:min(270px,100%);margin:0"><label>Departure station</label><select id="board-station">${options(S.boardStation)}</select></div><div><span class="tag warn">● SIMULATED STATUS</span></div></div><p class="tiny muted" style="margin:13px 0 0">We do not connect to Indian Railways or live GPS. All delays are illustrative and repeatable.</p></div>
 ${heading(`Departures from ${esc(S.boardStation)}`,`${S.board.length} scheduled sample train services`)}<div class="results">${S.board.length?S.board.map(x=>`<div class="service-card"><div class="detail-flex"><div><b>${esc(x.name)}</b><p class="tiny muted" style="margin:0">${esc(x.number)} · ${esc(x.from)} → ${esc(x.to)}</p></div><span class="tag ${x.delayMinutes?'warn':'success'}">${x.delayMinutes?'Estimated '+x.delayMinutes+' min delay':'On time'} (demo)</span></div><div class="twocol" style="margin-top:14px"><div class="meta-pair"><small>Scheduled departure</small><b>${esc(x.departure)}</b></div><div class="meta-pair"><small>Duration / waiting status</small><b>${esc(x.duration)} · ${esc(x.waitlist)}</b></div></div></div>`).join(''):`<div class="empty"><h3>No sample departures</h3><p class="muted">Choose a larger station such as Bengaluru or Chennai.</p></div>`}</div></main>`}
function help(){return `<main class="max content">${back()}${heading('Help & information','Answers to common questions about this educational project')}
 <div class="panel"><h3>❓ Frequently asked questions</h3><ul class="tip-list"><li><b>Are these real railway tickets?</b><br><span class="muted">No. They are local demonstration tickets, not valid for actual travel.</span></li><li><b>Does the QR code charge my bank account?</b><br><span class="muted">No. The demo pattern is intentionally not scannable and no banking details are requested.</span></li><li><b>Can I cancel a booking?</b><br><span class="muted">Yes. Go to My Tickets → View Ticket → Cancel Ticket → Confirm. The demo records the date and time and releases the seat.</span></li><li><b>Are flight and train times live?</b><br><span class="muted">No. This project uses preloaded examples and simulated delay labels. It has no live railway or airline API.</span></li><li><b>Will my tickets remain after closing the app?</b><br><span class="muted">Yes, on this laptop. The Java backend saves demo users and bookings to a local data file.</span></li><li><b>How are refunds handled?</b><br><span class="muted">A sample refund amount is calculated for the classroom demonstration. There is no real transfer of money.</span></li></ul></div>
 <div class="panel"><h3>🛠️ Technology used</h3><p><b>Frontend:</b> HTML5, CSS3, JavaScript (responsive web pages, forms, seat map, validation).</p><p><b>Backend:</b> Java 17 HTTP server, session login, password hashing, route/search/payment/cancellation APIs.</p><p><b>Storage:</b> Java local file persistence for sample routes, passenger accounts, tickets and cancellation history.</p><p class="muted tiny">The application runs locally using VS Code and Maven (or included Run_RailYatra.bat).</p></div>
 <div class="panel"><h3>💬 Your feedback</h3><p class="muted">Help improve this demonstration.</p><form id="feedback-form"><div class="field"><label>Experience rating</label><select name="rating"><option value="5">⭐⭐⭐⭐⭐ — Excellent</option><option value="4">⭐⭐⭐⭐ — Good</option><option value="3">⭐⭐⭐ — Okay</option><option value="2">⭐⭐ — Needs improvement</option><option value="1">⭐ — Poor</option></select></div><div class="field"><label>Message</label><textarea name="message" minlength="5" maxlength="800" placeholder="What should be improved?" required></textarea></div><button class="btn btn-primary" type="submit">Submit feedback</button></form></div></main>`}
function admin(){return `<main class="max content">${back()}${heading('Admin management dashboard','Demo service controls, new routes, ticket counts and sample data')}
 ${S.adminStats?`<div class="dashboard-grid">${[['Users',S.adminStats.passengers],['Services',S.adminStats.services],['Bookings',S.adminStats.bookings],['Cancelled',S.adminStats.cancellations],['Feedback',S.adminStats.feedback]].map(([name,value])=>`<div class="metric"><strong>${value}</strong><small>${name}</small></div>`).join('')}</div>`:''}
 <div class="panel" style="margin-top:17px"><h3>➕ Add a sample train or flight</h3><form id="admin-form"><div class="form-grid"><div class="field"><label>Type</label><select name="type"><option value="TRAIN">Train</option><option value="FLIGHT">Flight</option></select></div><div class="field"><label>Service number</label><input name="number" placeholder="EX123" required></div><div class="field"><label>Name</label><input name="name" placeholder="New Express" required></div><div class="field"><label>From city</label><input name="from" placeholder="Bengaluru" required></div><div class="field"><label>To city</label><input name="to" placeholder="Chennai" required></div><div class="field"><label>Duration</label><input name="duration" placeholder="5h 20m" required></div><div class="field"><label>Departure (24 h)</label><input type="time" name="departure" value="08:00" required></div><div class="field"><label>Arrival (24 h)</label><input type="time" name="arrival" value="13:20" required></div><div class="field"><label>Base fare (₹)</label><input type="number" name="fare" value="600" min="1" required></div><div class="field"><label>Seat capacity</label><input type="number" name="capacity" value="32" min="1" max="64" required></div></div><button type="submit" class="btn btn-primary">+ Add demo service</button></form></div>
 <div class="panel"><h3>⚙️ Manage existing services</h3><div class="results">${S.adminServices.map(x=>`<div class="detail-flex" style="padding:9px 0;border-bottom:1px solid var(--border)"><div><b>${esc(x.name)} ${esc(x.number)}</b><br><small class="muted">${esc(x.from)} → ${esc(x.to)} · ${rupee(x.fare)} · ${x.type}</small></div><button class="btn ${x.active?'btn-outline':'btn-green'} btn-sm" data-toggle="${attr(x.id)}">${x.active?'Disable':'Enable'}</button></div>`).join('')}</div></div></main>`;}
function drawer(){const links=[['home','🏠','Explore journeys'],['tickets','🎟️','My tickets & cancellations'],['board','📡','Station departure board'],['help','❓','Help & FAQs']];const items=links.map(([view,ico,label])=>`<button class="drawer-item" data-go="${view}"><span class="left"><span>${ico}</span>${label}</span><span>›</span></button>`).join('');
 $('#drawer').innerHTML=`<div class="drawer-head"><div class="detail-flex"><div class="brand"><span class="brand-mark">🚆</span><span><strong>Rail<span>Yatra</span></strong><small>TRAVEL MADE SIMPLE</small></span></div><button class="icon-button" data-action="drawer-close">✕</button></div><p style="font-size:13px;color:#c7dff7;margin:15px 0 0">Travel smart. Book easy. Explore more.</p></div><div class="drawer-list">${S.user?`<div class="profile-strip"><span class="avatar">${esc(S.user.name[0])}</span><div><b>${esc(S.user.name)}</b><small>${esc(S.user.email)}</small></div></div>`:`<button class="btn btn-primary btn-wide" data-action="login">Login / Create Account</button>`}
 <div class="drawer-divider"></div>${items}${S.user?.role==='ADMIN'?`<button class="drawer-item" data-go="admin"><span class="left">⚙️ Admin dashboard</span><span>›</span></button>`:''}<div class="drawer-divider"></div>
 <button class="drawer-item" data-action="timetable"><span class="left">⏱️ Refresh timetable</span><span>↻</span></button><button class="drawer-item" data-action="language"><span class="left">🌐 Language</span><b>${esc(languages[S.lang])}</b></button>
 <button class="drawer-item" data-action="theme"><span class="left">🌙 Dark / Light mode</span><b>${S.theme==='dark'?'Dark':'Light'}</b></button><button class="drawer-item" data-action="feedback"><span class="left">💬 Feedback</span><span>›</span></button>
 <button class="drawer-item" data-action="share"><span class="left">↗️ Share app</span><span>›</span></button><button class="drawer-item" data-action="clear-history"><span class="left">🗑️ Delete search history</span><span>›</span></button><div class="drawer-divider"></div>
 <button class="drawer-item" data-action="terms"><span class="left">📄 Terms of service</span><span>›</span></button><button class="drawer-item" data-action="licenses"><span class="left">📖 Open-source licenses</span><span>›</span></button><button class="drawer-item" data-action="upcoming"><span class="left">🎉 Upcoming features</span><span>›</span></button>${S.user?`<div class="drawer-divider"></div><button class="drawer-item" data-action="logout"><span class="left">🚪 Logout</span><span>›</span></button>`:''}</div><div class="drawer-note">© RailYatra learning project · Not affiliated with any railway, airline or payment provider.</div>`;
}
function toggleDrawer(open){const v=open===undefined?!$('#drawer').classList.contains('open'):open;$('#drawer').classList.toggle('open',v);$('#drawer-backdrop').classList.toggle('hidden',!v)}
function showModal(body,title='Details',wide=false){$('#modal').className='modal'+(wide?' wide':'');$('#modal').innerHTML=`<div class="modal-head"><h3>${title}</h3><button class="modal-close" data-action="close-modal" aria-label="Close">✕</button></div>${body}`;$('#modal-backdrop').classList.remove('hidden')}
function closeModal(){$('#modal-backdrop').classList.add('hidden')}
function loginModal(register=false){S.langShown=false;showModal(register?`<form id="register-form"><div class="field"><label>Full name</label><input name="name" required minlength="2" placeholder="Your full name"></div><div class="field"><label>Email address</label><input name="email" type="email" required placeholder="name@example.com"></div><div class="field"><label>Mobile number (optional)</label><input name="phone" placeholder="10-digit number"></div><div class="field"><label>Password (8+ characters)</label><input name="password" type="password" minlength="8" required placeholder="Create a password"></div><div class="banner">🔒 Passwords are hashed in the Java backend. This is an educational demonstration; no real ticket or payment. Do not enter real personal or banking information.</div><button class="btn btn-primary btn-wide" style="margin-top:15px">Create account</button><p class="tiny muted" style="text-align:center;margin-top:14px">Already registered? <button type="button" class="plain-link" data-action="login">Login</button></p></form>`:
 `<form id="login-form"><div class="field"><label>Email address</label><input name="email" type="email" required placeholder="you@example.com"></div><div class="field"><label>Password</label><input name="password" type="password" required placeholder="Your password"></div><button class="btn btn-primary btn-wide">Login securely →</button></form><div class="separator"></div>${S.publicDemo?'<div class="banner">Public educational demo. Please use a made-up name and email and a password you do not use elsewhere. The site can reset its data.</div>':'<div class="banner"><b>Sample passenger login</b><br><small>demo@railyatra.test / Demo@1234</small><br><b>Sample administrator login</b><br><small>admin@railyatra.test / Admin@123</small></div>'}<p class="tiny muted" style="text-align:center;margin-top:16px">New to RailYatra? <button class="plain-link" data-action="register">Create a free demo account</button></p>`,register?'Create passenger account':'Welcome back');}
function cancelModal(){const x=S.ticket;if(!x||x.status!=='CONFIRMED')return;const d1=new Date(S.ticket.date+'T00:00:00'),d2=new Date(todayLocal()+'T00:00:00'),days=Math.round((d1-d2)/86400000),rate=days>=2?.90:days===1?.70:.50;const refund=Math.round(x.total*rate);
 showModal(`<div class="banner danger">⚠️ Are you sure you want to cancel this demo ticket? Seats will be released immediately.</div><div class="summary-row"><span>Booking PNR</span><strong>${esc(x.pnr)}</strong></div><div class="summary-row"><span>Train / flight</span><strong>${esc(x.service.name)}</strong></div><div class="summary-row"><span>Travel date</span><strong>${esc(x.date)}</strong></div><div class="summary-row"><span>Demo amount paid</span><strong>${rupee(x.total)}</strong></div><div class="summary-row"><span>Demo cancellation deduction</span><strong>${rupee(x.total-refund)}</strong></div><div class="summary-total"><span>Estimated demo refund</span><b>${rupee(refund)}</b></div><div class="banner warning" style="margin-top:14px">Cancellation time will be recorded in Indian Standard Time. Refund amount is only a calculation; no money is transferred.</div><div class="modal-footer"><button class="btn btn-outline" data-action="close-modal">Keep ticket</button><button class="btn btn-red" data-action="confirm-cancel">Yes, cancel ticket</button></div>`,'Confirm ticket cancellation');}
function languageModal(){showModal(`<p class="muted">Choose a language. Main navigation, search labels, and core buttons are translated; other detailed forms stay in English.</p><div class="pay-methods" style="grid-template-columns:repeat(2,1fr)">${Object.entries(languages).map(([code,name])=>`<button class="pay-option ${S.lang===code?'active':''}" data-language="${code}"><span class="pay-ico">🌐</span><b>${esc(name)}</b></button>`).join('')}</div>`,'Language preferences')}
function detailsModal(action){let title='',content='';if(action==='terms'){title='Terms of service';content=`<p>This is a <b>student demonstration project</b>. It is not connected with Indian Railways, IRCTC, Google Pay, PhonePe, any airline, or any real payment provider.</p><p>All routes, seat statuses, timetable changes, ticket payments, PNRs and refunds are simulated. The demonstration cannot provide real transportation or collect real money.</p><p>Only create demo accounts. Do not enter sensitive bank, card or identity information.</p>`}
 if(action==='licenses'){title='Open-source information';content=`<p>Project code uses Java 17 standard library HTTP server, JavaScript, CSS and HTML. The optional font styling uses Google Fonts with system font fallback.</p><p>Icons are rendered with Unicode characters, CSS and a few inline SVGs. No proprietary Google / train tracking code is copied.</p>`}
 if(action==='upcoming'){title='Upcoming feature ideas';content=`<ul class="tip-list"><li>🛰️ Real train delay tracking (would need an authorized external API)</li><li>📍 Map-based station location (would require a map API)</li><li>🧾 Printable PDF tickets</li><li>🌍 Full multilingual translations</li><li>🔔 Email notifications and OTP login (would require a delivery service)</li><li>💳 Actual verified payment gateway (would require merchant onboarding)</li></ul><p class="muted tiny">These are future ideas, not current live integrations.</p>`}
 showModal(content,title);}
function render(){document.body.classList.toggle('dark',S.theme==='dark');authHeader();drawer();
 let html;
 switch(S.view){case 'home':html=home();break;case 'booking':html=booking();break;case 'payment':html=payment();break;case 'success':case 'ticket':html=ticketView();break;case 'tickets':html=tickets();break;case 'board':html=board();break;case 'help':html=help();break;case 'admin':html=admin();break;default:html=home();}
 app.innerHTML=html;
}
async function go(view){toggleDrawer(false);if(view==='tickets'){if(S.user)try{const v=await api('/api/tickets');S.tickets=v.tickets}catch(e){msg(e.message)}}
 if(view==='board')await loadBoard();if(view==='admin')await loadAdmin();S.view=view;render();window.scrollTo({top:0,behavior:'smooth'});}
async function loadBoard(){try{const p=new URLSearchParams({station:S.boardStation});S.board=(await api('/api/stationboard?'+p)).services;}catch(e){msg(e.message);S.board=[]}}
async function loadAdmin(){if(S.user?.role!=='ADMIN'){msg('Login as a demo administrator');return}
 try{const [a,b]=await Promise.all([api('/api/admin/overview'),api('/api/services?all=1&date='+encodeURIComponent(S.date))]);S.adminStats=a;S.adminServices=b.services;}catch(e){msg(e.message)}}
function saveDrafts(){document.querySelectorAll('[data-pfield]').forEach(el=>{const i=Number(el.dataset.index);if(S.passengers[i])S.passengers[i][el.dataset.pfield]=el.value});}
function switchPassenger(delta){saveDrafts();const n=S.count+delta;if(n<1||n>6)return;S.count=n;while(S.passengers.length<n)S.passengers.push({name:'',age:'',gender:'Female'});S.passengers.length=n;if(S.selectedSeats.length>n)S.selectedSeats.length=n;render();}
async function book(id){const s=S.results.find(x=>x.id===id);if(!s){msg('Journey no longer available. Search again.');return}if(!S.user){S.authReturn='booking';S.selected=s;S.travelClass=s.type==='TRAIN'?'Sleeper':'Economy';loginModal();msg('Login to continue booking');return}
 S.selected=s;S.travelClass=s.type==='TRAIN'?'Sleeper':'Economy';S.count=1;S.passengers=[{name:'',age:'',gender:'Female'}];S.selectedSeats=[];S.insurance=false;go('booking');}
async function startCheckout(){saveDrafts();if(S.selectedSeats.length!==S.count){msg(`Select exactly ${S.count} seat(s) before payment.`);return}
 const values={serviceId:S.selected.id,date:S.date,travelClass:S.travelClass,pcount:S.count,seats:S.selectedSeats.join(','),insurance:S.insurance?'1':'0'};
 for(let i=0;i<S.count;i++){const p=S.passengers[i]||{};values['p'+i+'name']=p.name;values['p'+i+'age']=p.age;values['p'+i+'gender']=p.gender;}
 try{const c=await api('/api/checkout',values);S.checkout=c;S.paymentStage=0;S.paymentMode='UPI QR';go('payment')}catch(e){msg(e.message)}
}
async function pay(){if(!$('#ack-demo')?.checked){msg('Confirm that you understand this is a demo payment.');return}
 try{const ticket=await api('/api/payment/complete',{checkoutId:S.checkout.id,paymentMode:S.paymentMode});S.ticket=ticket;S.checkout=null;S.view='success';render();window.scrollTo({top:0,behavior:'smooth'});msg('Demo payment completed. Your sample ticket is booked!')}
 catch(e){msg(e.message)}
}
async function viewTicket(pnr){try{S.ticket=await api('/api/ticket?'+new URLSearchParams({pnr}));S.view='ticket';render();window.scrollTo({top:0,behavior:'smooth'})}catch(e){msg(e.message)}}
async function cancelTicket(){try{S.ticket=await api('/api/tickets/cancel',{pnr:S.ticket.pnr,confirm:'YES'});closeModal();S.view='ticket';render();msg('Ticket cancelled. Cancellation date and demo refund are saved.')}catch(e){msg(e.message)}}
function downloadTicket(){const x=S.ticket;if(!x)return;const ss=x.service;const lines=[
 'RAILYATRA DEMO E-TICKET — NOT VALID FOR TRAVEL','',`PNR: ${x.pnr}`,`Status: ${x.status}`,`Journey: ${ss.name} (${ss.number})`,`${ss.from} -> ${ss.to}`,`Date: ${x.date}`,`Time: ${ss.departure} -> ${ss.arrival}`,`Duration: ${ss.duration}`,`Class: ${x.travelClass}`,`Demo payment method: ${x.method}`,`Demo payment time: ${x.paidAt}`,`Demo payment reference: ${x.paymentReference}`,
 '', 'PASSENGERS',...x.passengers.map((p,i)=>`${i+1}. ${p.name} | Age ${p.age} | ${p.gender} | Seat ${x.seats[i]}`),'',`Base fare: Rs. ${x.fare}`,`Tax: Rs. ${x.tax}`,`Fee: Rs. ${x.fee}`,`Insurance: Rs. ${x.insurance}`,`TOTAL DEMO AMOUNT: Rs. ${x.total}`,
 ...(x.status==='CANCELLED'?[``,`CANCELLED AT: ${x.cancelledAt}`,`DEMO REFUND: Rs. ${x.refund}`,`${x.refundStatus}`]:[]),'', 'EDUCATIONAL SIMULATION. NO REAL BOOKING, PAYMENT OR REFUND.'
 ];const blob=new Blob([lines.join('\r\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='RailYatra_'+x.pnr+'.txt';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);msg('Your demo ticket was downloaded.');}
function numberModal(){showModal(`<p class="muted">Search sample trains or flights using the number or name (e.g. 12608 or Lalbagh).</p><form id="number-form"><div class="field"><label>Service number or name</label><input name="query" required placeholder="Example: 12608" autofocus></div><div class="field"><label>Mode</label><select name="type"><option value="TRAIN">Train</option><option value="FLIGHT">Flight</option></select></div><button type="submit" class="btn btn-primary btn-wide">Search service →</button></form>`,'Search by train or flight number');}
async function init(){try{const d=await api('/api/bootstrap');S.stations=Array.from(d.stations);S.user=d.user;S.publicDemo=!!d.publicDemo;S.date=d.today?(()=>{let z=new Date(d.today+'T12:00:00');z.setDate(z.getDate()+1);return `${z.getFullYear()}-${String(z.getMonth()+1).padStart(2,'0')}-${String(z.getDate()).padStart(2,'0')}`})():future();render();search(false)}catch(e){app.innerHTML=`<main class="max content"><div class="empty"><h2>Cannot connect to RailYatra server</h2><p>${esc(e.message)}</p><p>Start the Java backend with <code>mvn compile exec:java</code> and refresh this page.</p></div></main>`;}}
$('#menu-button').addEventListener('click',()=>toggleDrawer());$('#home-logo').addEventListener('click',()=>go('home'));$('#drawer-backdrop').addEventListener('click',()=>toggleDrawer(false));$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
document.addEventListener('change',async e=>{
 if(e.target.id==='search-date')S.date=e.target.value;
 if(e.target.id==='from')S.from=e.target.value;
 if(e.target.id==='to')S.to=e.target.value;
 if(e.target.id==='booking-class'){saveDrafts();S.travelClass=e.target.value;render()}
 if(e.target.id==='insurance'){saveDrafts();S.insurance=e.target.checked;render()}
 if(e.target.id==='board-station'){S.boardStation=e.target.value;await loadBoard();render()}
 if(e.target.matches('[data-pfield]')){const i=Number(e.target.dataset.index);if(S.passengers[i])S.passengers[i][e.target.dataset.pfield]=e.target.value}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-pfield]')){const i=Number(e.target.dataset.index);if(S.passengers[i])S.passengers[i][e.target.dataset.pfield]=e.target.value}});
document.addEventListener('click',async e=>{
 const target=e.target.closest('button');if(!target)return;
 if(target.dataset.go){await go(target.dataset.go);return}
 if(target.dataset.mode){changeMode(target.dataset.mode);return}
 if(target.dataset.book){await book(target.dataset.book);return}
 if(target.dataset.seat){const n=Number(target.dataset.seat);if(S.selectedSeats.includes(n))S.selectedSeats=S.selectedSeats.filter(z=>z!==n);else if(S.selectedSeats.length<S.count)S.selectedSeats.push(n);else{msg('You already selected a seat for each passenger.');return}saveDrafts();render();return}
 if(target.dataset.pay){S.paymentMode=target.dataset.pay;S.paymentStage=0;render();return}
 if(target.dataset.ticket){await viewTicket(target.dataset.ticket);return}
 if(target.dataset.history!==undefined){const h=S.history[Number(target.dataset.history)];if(!h)return;S.mode=h.type;S.from=h.from;S.to=h.to;S.date=h.date<todayLocal()?future():h.date;S.query='';await search();return}
 if(target.dataset.toggle){try{await api('/api/admin/toggle',{id:target.dataset.toggle});await loadAdmin();render();msg('Demo service updated')}catch(err){msg(err.message)}return}
 if(target.dataset.language){S.lang=target.dataset.language;localStorage.setItem('ry_lang',S.lang);closeModal();render();msg('Language preference updated.');return}
 const action=target.dataset.action;if(!action)return;
 switch(action){
 case 'swap':{const from=$('#from'),to=$('#to');if(from&&to){const a=from.value;from.value=to.value;to.value=a;S.from=from.value;S.to=to.value}break}
 case 'drawer-close':toggleDrawer(false);break;
 case 'login':toggleDrawer(false);loginModal();break;
 case 'register':loginModal(true);break;
 case 'close-modal':closeModal();break;
 case 'logout':try{await api('/api/auth/logout',{});S.user=null;S.tickets=[];closeModal();go('home');msg('You are logged out.')}catch(err){msg(err.message)}break;
 case 'add-passenger':switchPassenger(1);break;
 case 'remove-passenger':switchPassenger(-1);break;
 case 'checkout':await startCheckout();break;
 case 'payment-next':S.paymentStage=1;render();break;
 case 'payment-back':S.paymentStage=0;render();break;
 case 'complete-payment':await pay();break;
 case 'cancel-preview':cancelModal();break;
 case 'confirm-cancel':await cancelTicket();break;
 case 'download-ticket':downloadTicket();break;
 case 'print-ticket':window.print();break;
 case 'open-number':numberModal();break;
 case 'theme':S.theme=S.theme==='dark'?'light':'dark';localStorage.setItem('ry_theme',S.theme);toggleDrawer(false);render();msg(`${S.theme==='dark'?'Dark':'Light'} mode enabled`);break;
 case 'language':toggleDrawer(false);languageModal();break;
 case 'timetable':toggleDrawer(false);await search(false);msg('Sample timetable refreshed (not live data).');break;
 case 'clear-history':S.history=[];localStorage.removeItem('ry_history');toggleDrawer(false);render();msg('Search history cleared');break;
 case 'feedback':toggleDrawer(false);go('help');break;
 case 'share':{toggleDrawer(false);try{await navigator.clipboard.writeText(location.origin);msg(S.publicDemo?'Public website link copied.':'Local demo URL copied (works on this laptop).')}catch{showModal(`<p>Your local demo URL:</p><p><code>${esc(location.origin)}</code></p><p>To share with other devices, hosting and network settings would be required.</p>`,'Share RailYatra')}break}
 case 'terms':case 'licenses':case 'upcoming':toggleDrawer(false);detailsModal(action);break;
 }
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['search-form','login-form','register-form','number-form','feedback-form','admin-form'].includes(f.id))return;
 e.preventDefault();const values=Object.fromEntries(new FormData(f));
 if(f.id==='search-form'){S.query='';S.from=$('#from').value;S.to=$('#to').value;S.date=$('#search-date').value;if(S.from===S.to){msg('Choose different departure and destination stations.');return}await search();return}
 if(f.id==='number-form'){S.query=values.query.trim();S.mode=values.type;S.travelClass=S.mode==='TRAIN'?'Sleeper':'Economy';closeModal();S.view='home';await search(false);return}
 if(f.id==='login-form'||f.id==='register-form')try{S.user=await api('/api/auth/'+(f.id==='login-form'?'login':'register'),values);closeModal();S.view=S.authReturn==='booking'&&S.selected?'booking':'home';S.authReturn='home';render();msg('Welcome to RailYatra, '+S.user.name+'!');}catch(err){msg(err.message)}
 if(f.id==='feedback-form')try{await api('/api/feedback',values);f.reset();msg('Thank you for your feedback!')}catch(err){if(err.message.includes('log in')){loginModal()}else msg(err.message)}
 if(f.id==='admin-form')try{await api('/api/admin/services',values);await loadAdmin();render();msg('Sample service added!')}catch(err){msg(err.message)}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();toggleDrawer(false)}});
init();
